package com.customrpg.managers;

import com.customrpg.CustomRPG;
import com.customrpg.players.PlayerTalents;
import com.customrpg.talents.*;
import com.customrpg.utils.SkillDamageGuard;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.entity.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.*;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.plugin.PluginManager;
import org.bukkit.util.BoundingBox;
import org.bukkit.util.Vector;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class DarkTalentSkillsTest {
    CustomRPG plugin;World world;Player player;TalentManager manager;ExpandedTalentSkills combat;DarkTalentSkills skills;PlayerTalents learned;PluginManager events;
    final List<Entity> nearby=new ArrayList<>();final Map<UUID,Double> health=new HashMap<>(),speed=new HashMap<>();final Map<String,Talent> definitions=new HashMap<>();
    @BeforeEach void setup(){
        plugin=mock(CustomRPG.class);var server=mock(Server.class);events=mock(PluginManager.class);when(plugin.getServer()).thenReturn(server);when(server.getPluginManager()).thenReturn(events);when(plugin.getLogger()).thenReturn(java.util.logging.Logger.getAnonymousLogger());
        world=mock(World.class);when(world.isChunkLoaded(anyInt(),anyInt())).thenReturn(true);when(world.getMinHeight()).thenReturn(-64);when(world.getMaxHeight()).thenReturn(320);var border=mock(WorldBorder.class);when(world.getWorldBorder()).thenReturn(border);when(border.isInside(any())).thenReturn(true);
        player=mock(Player.class);when(player.getUniqueId()).thenReturn(UUID.randomUUID());when(player.getWorld()).thenReturn(world);when(player.isOnline()).thenReturn(true);when(player.isValid()).thenReturn(true);when(player.getGameMode()).thenReturn(GameMode.SURVIVAL);when(player.getLocation()).thenAnswer(i->new Location(world,0,64,0));when(player.getEyeLocation()).thenAnswer(i->new Location(world,0,65.5,0));when(player.getEyeHeight()).thenReturn(1.5);when(player.hasLineOfSight(any(Entity.class))).thenReturn(true);
        learned=new PlayerTalents();manager=mock(TalentManager.class);when(plugin.getTalentManager()).thenReturn(manager);when(manager.getPlayerTalents(player)).thenReturn(learned);when(manager.findTalent(anyString())).thenAnswer(i->definitions.get(i.getArgument(0)));
        combat=spy(new ExpandedTalentSkills(plugin,()->0,mock(ExpandedTalentSkills.StatusEffects.class)));var motion=mock(DarkTalentSkills.Motion.class);doAnswer(i->{LivingEntity e=i.getArgument(0);speed.put(e.getUniqueId(),i.getArgument(1));return null;}).when(motion).set(any(),anyDouble());doAnswer(i->{LivingEntity e=i.getArgument(0);speed.remove(e.getUniqueId());return null;}).when(motion).clear(any());skills=new DarkTalentSkills(plugin,combat,motion);
        when(world.getNearbyEntities(any(Location.class),anyDouble(),anyDouble(),anyDouble())).thenAnswer(i->new ArrayList<>(nearby));when(world.getBlockAt(anyInt(),anyInt(),anyInt())).thenAnswer(i->{int x=i.getArgument(0),y=i.getArgument(1),z=i.getArgument(2);var b=mock(Block.class);when(b.isPassable()).thenReturn(y>63);when(b.getBoundingBox()).thenReturn(new BoundingBox(x,y,z,x+1,y+1,z+1));return b;});when(world.getBlockAt(any(Location.class))).thenAnswer(i->{Location at=i.getArgument(0);return world.getBlockAt(at.getBlockX(),at.getBlockY(),at.getBlockZ());});
    }
    LivingEntity mob(double x,double z){var e=mock(Zombie.class);when(e.getUniqueId()).thenReturn(UUID.randomUUID());when(e.getWorld()).thenReturn(world);when(e.isValid()).thenReturn(true);when(e.getMaxHealth()).thenReturn(1000.0);when(e.getLocation()).thenAnswer(i->new Location(world,x,64,z));when(e.getEyeLocation()).thenAnswer(i->new Location(world,x,65.5,z));when(e.getPersistentDataContainer()).thenReturn(mock(PersistentDataContainer.class));health.put(e.getUniqueId(),1000.0);when(e.getHealth()).thenAnswer(i->health.get(e.getUniqueId()));when(e.isDead()).thenAnswer(i->health.get(e.getUniqueId())<=0);doAnswer(i->{health.compute(e.getUniqueId(),(id,hp)->Math.max(0,hp-(double)i.getArgument(0)));return null;}).when(e).damage(anyDouble(),eq(player));nearby.add(e);return e;}
    Talent talent(DarkSkill s){var t=new Talent(s.id,s.title,"test",TalentType.ACTIVE,TalentBranch.DARK,3,1,List.of(),Talent.PrerequisiteMode.ALL,s.slot,"WITHER_ROSE","凋零玫瑰",s.cooldown,s.mana,0,"RIGHT_CLICK");var d=new Talent.TalentLevelData();d.addEffect("baseDamage",s.damage);d.addEffect("range",s.range);t.addLevelData(1,d);definitions.put(s.id,t);learned.setTalentLevel(s.id,1);if(s==DarkSkill.ECLIPSE)learned.setUltimateSkill(s.id);else if(!Arrays.asList(learned.getSelectedSkills()).contains(s.id)){int i=0;while(i<4&&learned.getSelectedSkills()[i]!=null)i++;learned.setSelectedSkill(i,s.id);}return t;}
    void aim(LivingEntity target){for(int range:new int[]{10,11,12})doReturn(target).when(combat).aim(player,range);}
    void ticks(int n){for(int i=0;i<n;i++)skills.tick();}
    EntityDamageByEntityEvent attack(LivingEntity attacker,double n){var e=mock(EntityDamageByEntityEvent.class);when(e.getEntity()).thenReturn(player);when(e.getDamager()).thenReturn(attacker);var value=new AtomicReference<>(n);when(e.getDamage()).thenAnswer(i->value.get());when(e.getFinalDamage()).thenAnswer(i->value.get());doAnswer(i->{value.set(i.getArgument(0));return null;}).when(e).setDamage(anyDouble());return e;}
    @Test void rendTwoBladesAreFourTicksApartAndDoNotLoseTheirSecondHitToVanillaHurtFrames(){var target=mob(0,6);aim(target);var frames=new AtomicInteger();var last=new double[]{0};when(target.getNoDamageTicks()).thenAnswer(i->frames.get());doAnswer(i->{frames.set(i.getArgument(0));return null;}).when(target).setNoDamageTicks(anyInt());doAnswer(i->{double n=i.getArgument(0);double actual=frames.get()>0?Math.max(0,n-last[0]):n;last[0]=n;frames.set(20);health.compute(target.getUniqueId(),(id,hp)->hp-actual);return null;}).when(target).damage(anyDouble(),eq(player));skills.cast(player,talent(DarkSkill.REND),1);ticks(4);assertEquals(1000,health.get(target.getUniqueId()));ticks(1);assertEquals(997,health.get(target.getUniqueId()));ticks(3);assertEquals(997,health.get(target.getUniqueId()));ticks(1);assertEquals(993,health.get(target.getUniqueId()));assertEquals(20,frames.get());}
    @Test void aCastMarksOnlyOnceAndThirdLayerWaitsForTheNextDirectHit(){var target=mob(0,6);aim(target);var rend=talent(DarkSkill.REND);skills.cast(player,rend,1);ticks(10);skills.cast(player,rend,1);ticks(10);assertEquals(986,health.get(target.getUniqueId()));}
    @Test void stitchAppliesTwentyFivePercentSlowAndFifteenPercentOutgoingWeakness(){var target=mob(0,6);aim(target);skills.cast(player,talent(DarkSkill.STITCH),1);verify(target).damage(2,player);assertEquals(.25,speed.get(target.getUniqueId()));assertEquals(.85,skills.outgoingMultiplier(target),1e-8);ticks(80);assertEquals(1,skills.outgoingMultiplier(target));assertEquals(0,speed.getOrDefault(target.getUniqueId(),0.0));}
    @Test void threeStitchesDoNotBurstUntilTheFourthAndAntiHealExpires(){var target=mob(0,6);aim(target);var t=talent(DarkSkill.STITCH);for(int i=0;i<3;i++)skills.cast(player,t,1);verify(target,never()).damage(3,player);skills.cast(player,t,1);verify(target,times(1)).damage(3,player);var heal=mock(EntityRegainHealthEvent.class);when(heal.getEntity()).thenReturn(target);when(heal.getAmount()).thenReturn(10.0);skills.weakenHealing(heal);verify(heal).setAmount(8.5);ticks(80);clearInvocations(heal);skills.weakenHealing(heal);verify(heal).setAmount(10);}
    @Test void echoRecordsFourteenActualDirectDamageAndReplaysOnlyOnceWithoutRenormalizing(){var target=mob(0,6);aim(target);skills.cast(player,talent(DarkSkill.ECHO),1);var rend=talent(DarkSkill.REND);skills.cast(player,rend,1);ticks(10);skills.cast(player,rend,1);ticks(10);var normalized=new AtomicBoolean();doAnswer(i->{double n=i.getArgument(0);if(Math.abs(n-4.9)<1e-7){assertTrue(SkillDamageGuard.isNormalized(player));assertTrue(SkillDamageGuard.isPeriodic(player));normalized.set(true);}health.compute(target.getUniqueId(),(id,hp)->hp-n);return null;}).when(target).damage(anyDouble(),eq(player));ticks(60);assertTrue(normalized.get());verify(target,times(1)).damage(eq(4.8999999999999995),eq(player));ticks(80);assertEquals(981.1,health.get(target.getUniqueId()),1e-8);}
    @Test void echoWithNoOwnDarkDirectDamageCannotInventDamageOrRecordOtherPlayers(){var target=mob(0,6);aim(target);skills.cast(player,talent(DarkSkill.ECHO),1);health.put(target.getUniqueId(),900.0);ticks(100);verify(target,never()).damage(anyDouble(),eq(player));}
    @Test void curtainSweepsFastCrossingsAndEachEnemyCanTriggerOnlyOnce(){var target=mob(0,6);skills.cast(player,talent(DarkSkill.CURTAIN),1);skills.mobMove(new io.papermc.paper.event.entity.EntityMoveEvent(target,new Location(world,0,64,3),new Location(world,0,64,7)));skills.mobMove(new io.papermc.paper.event.entity.EntityMoveEvent(target,new Location(world,0,64,7),new Location(world,0,64,3)));verify(target,times(1)).damage(4,player);ticks(1);assertEquals(.25,speed.get(target.getUniqueId()));}
    @Test void curtainDoesNotHitBesideAboveOrOutsideItsFiveSecondLifetime(){var target=mob(0,6);skills.cast(player,talent(DarkSkill.CURTAIN),1);skills.mobMove(new io.papermc.paper.event.entity.EntityMoveEvent(target,new Location(world,4,64,3),new Location(world,4,64,7)));skills.mobMove(new io.papermc.paper.event.entity.EntityMoveEvent(target,new Location(world,0,68,3),new Location(world,0,68,7)));ticks(100);skills.mobMove(new io.papermc.paper.event.entity.EntityMoveEvent(target,new Location(world,0,64,3),new Location(world,0,64,7)));verify(target,never()).damage(anyDouble(),eq(player));}
    @Test void stepWaitsNineTicksAndRespectsWallsAndNeverGrantsInvulnerability(){var destination=new AtomicReference<Location>();when(player.collidesAt(any(Location.class))).thenAnswer(i->((Location)i.getArgument(0)).getZ()>=3);when(player.teleport(any(Location.class),eq(PlayerTeleportEvent.TeleportCause.PLUGIN))).thenAnswer(i->{assertTrue(skills.internalStep(player));destination.set(i.getArgument(0));return true;});assertTrue(skills.cast(player,talent(DarkSkill.STEP),1));ticks(8);verify(player,never()).teleport(any(Location.class),any(PlayerTeleportEvent.TeleportCause.class));ticks(1);assertNotNull(destination.get());assertTrue(destination.get().getZ()<3);verify(player,never()).setInvulnerable(anyBoolean());}
    @Test void stepWithoutLoadedSafeTerrainCannotStart(){when(world.isChunkLoaded(anyInt(),anyInt())).thenReturn(false);assertFalse(skills.cast(player,talent(DarkSkill.STEP),1));ticks(20);verify(player,never()).teleport(any(Location.class),any(PlayerTeleportEvent.TeleportCause.class));}
    @Test void servantHasNoEntityAiAndAttacksOnlyFourTimesWithOnlyOneMarkPerVictim(){var target=mob(0,4);skills.cast(player,talent(DarkSkill.SERVANT),1);ticks(23);verify(target,never()).damage(anyDouble(),eq(player));ticks(100);verify(target,times(4)).damage(2,player);verify(target,never()).damage(3,player);verify(world,never()).spawnEntity(any(Location.class),any(EntityType.class));}
    @Test void fractureCapsAbsorptionAtEightAndOnlyConsumesAnAcceptedDirectHit(){var enemy=mob(0,4);skills.cast(player,talent(DarkSkill.FRACTURE),1);var cancelled=attack(enemy,50);skills.mitigate(cancelled);assertEquals(42,cancelled.getFinalDamage(),1e-8);when(cancelled.isCancelled()).thenReturn(true);skills.accepted(cancelled);var accepted=attack(enemy,50);skills.mitigate(accepted);skills.accepted(accepted);assertEquals(42,accepted.getFinalDamage(),1e-8);assertEquals(.9,skills.outgoingMultiplier(enemy),1e-8);var later=attack(enemy,10);skills.mitigate(later);assertEquals(10,later.getFinalDamage());ticks(40);assertEquals(1,skills.outgoingMultiplier(enemy));}
    @Test void eclipseHitsAtTwentyFiveTicksThenThreeResidualPulsesForNineteenAndNeverMovesBosses(){var target=mob(0,12);skills.cast(player,talent(DarkSkill.ECLIPSE),1);ticks(24);verify(target,never()).damage(anyDouble(),eq(player));ticks(1);verify(target).damage(13,player);var heal=mock(EntityRegainHealthEvent.class);when(heal.getEntity()).thenReturn(target);when(heal.getAmount()).thenReturn(10.0);skills.weakenHealing(heal);verify(heal).setAmount(8);ticks(100);verify(target,times(3)).damage(2,player);assertEquals(981,health.get(target.getUniqueId()));verify(target,never()).teleport(any(Location.class),any(PlayerTeleportEvent.TeleportCause.class));}
    @Test void cancelledCurseCannotApplyMovementOrOutgoingDebuffs(){var target=mob(0,6);aim(target);doAnswer(i->{if(i.getArgument(0) instanceof DarkControlEvent e)e.setCancelled(true);return null;}).when(events).callEvent(any());skills.cast(player,talent(DarkSkill.STITCH),1);assertTrue(speed.isEmpty());assertEquals(1,skills.outgoingMultiplier(target));}
    @Test void resetWorldChangesAndShutdownRemoveDebuffsAndQueuedHits(){var target=mob(0,6);aim(target);skills.cast(player,talent(DarkSkill.STITCH),1);skills.cast(player,talent(DarkSkill.REND),1);clearInvocations(target);skills.cancel(player);ticks(20);verify(target,never()).damage(anyDouble(),eq(player));assertEquals(1,skills.outgoingMultiplier(target));skills.cast(player,talent(DarkSkill.REND),1);when(player.getWorld()).thenReturn(mock(World.class));ticks(20);verify(target,never()).damage(anyDouble(),eq(player));skills.shutdown();assertEquals(0,speed.getOrDefault(target.getUniqueId(),0.0));}
    @Test void absorbedDirectDamageCannotBeRecordedAsActualLifeLossByEcho(){var target=mob(0,6);aim(target);var shield=new double[]{30};when(target.getAbsorptionAmount()).thenAnswer(x->shield[0]);doAnswer(x->{shield[0]-=(double)x.getArgument(0);return null;}).when(target).damage(anyDouble(),eq(player));skills.cast(player,talent(DarkSkill.ECHO),1);skills.cast(player,talent(DarkSkill.REND),1);ticks(100);verify(target,times(1)).damage(3,player);verify(target,times(1)).damage(4,player);verify(target,times(2)).damage(anyDouble(),eq(player));assertEquals(1000,health.get(target.getUniqueId()));}
    @Test void cancelledBrandBonusDoesNotConsumeMarksOrStartItsTenSecondImmunity(){var target=mob(0,6);aim(target);var stitch=talent(DarkSkill.STITCH);for(int i=0;i<3;i++)skills.cast(player,stitch,1);var reject=new AtomicBoolean(true);doAnswer(x->{double n=x.getArgument(0);if(n==3&&reject.get())return null;health.compute(target.getUniqueId(),(id,hp)->hp-n);return null;}).when(target).damage(anyDouble(),eq(player));skills.cast(player,stitch,1);var heal=mock(EntityRegainHealthEvent.class);when(heal.getEntity()).thenReturn(target);when(heal.getAmount()).thenReturn(10.0);skills.weakenHealing(heal);verify(heal).setAmount(10);reject.set(false);skills.cast(player,stitch,1);clearInvocations(heal);skills.weakenHealing(heal);verify(heal).setAmount(8.5);}

    @Test void diagonalCurtainFeedbackUsesTheCrossingPointRatherThanTheEndOfTheMovement(){
        var service=mock(com.customrpg.vfx.BukkitVfxService.class);when(plugin.getVfxService()).thenReturn(service);var captured=new AtomicReference<com.customrpg.vfx.VfxRuntime.Effect>();
        when(service.dark(eq(player),anyString(),any(Location.class),any(Vector.class),any(),any(),any(),anyInt())).thenAnswer(x->{if(x.getArgument(4) instanceof com.customrpg.vfx.DarkVfx.Curtain)captured.set(x.getArgument(4));return null;});
        var target=mob(10,11);skills.cast(player,talent(DarkSkill.CURTAIN),1);skills.mobMove(new io.papermc.paper.event.entity.EntityMoveEvent(target,new Location(world,0,64,3),new Location(world,10,64,11)));verify(target).damage(4,player);
        var points=new ArrayList<com.customrpg.vfx.VfxMath.V>();var worldId=UUID.randomUUID();var viewer=UUID.randomUUID();var transport=new com.customrpg.vfx.VfxRuntime.Transport(){public boolean valid(com.customrpg.vfx.VfxRuntime.Pose p){return true;}public List<com.customrpg.vfx.VfxRuntime.Viewer> viewers(com.customrpg.vfx.VfxRuntime.Pose p,com.customrpg.vfx.VfxRuntime.Mode m,double d){return List.of(new com.customrpg.vfx.VfxRuntime.Viewer(viewer,worldId,com.customrpg.vfx.VfxMath.V.ZERO,com.customrpg.vfx.VfxRuntime.Quality.HIGH));}public boolean particle(UUID v,UUID w,com.customrpg.vfx.VfxMath.V at,com.customrpg.vfx.VfxRuntime.Paint paint){points.add(at);return true;}public boolean sound(UUID v,UUID w,com.customrpg.vfx.VfxMath.V at,String s,float a,float b){return true;}};
        var runtime=new com.customrpg.vfx.VfxRuntime(transport,com.customrpg.vfx.VfxRuntime.Limits.defaults(),()->0);runtime.play("dark_curtain",new com.customrpg.vfx.VfxRuntime.Pose(player.getUniqueId(),worldId,com.customrpg.vfx.VfxMath.V.ZERO,com.customrpg.vfx.VfxMath.V.FORWARD,0,null),com.customrpg.vfx.VfxRuntime.Mode.PREVIEW,captured.get(),42,false,0,10);runtime.tick();assertFalse(points.isEmpty());assertTrue(points.stream().allMatch(at->Math.abs(at.x())<4));
    }

}
